insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c7511$regiones-comerciales-de-vendedores$c7511$), $c7512$SELECT
  id,
  store_name,
  country,
  CASE country
    WHEN 'MX' THEN 'Norteamérica'
