insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c7774$dias-de-entrega-por-envio$c7774$), $c7775$SELECT order_id, shipped_at, delivered_at, EXTRACT(DAY FROM AGE(delivered_at::date, shipped_at::date)) AS delivery_days FROM shipments WHERE shipped_at >= DATE '2025-09-01' AND shipped_at < DATE '2025-09-08' AND delivered_at IS NOT NULL ORDER BY delivery_days DESC, order_id;$c7775$, false, $c7776$Con AGE y EXTRACT$c7776$, 2);

