insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c7810$entregas-fuera-de-la-promesa$c7810$), $c7811$SELECT id,
       placed_at,
       delivered_at,
